function updateHud(){ui.lives.textContent='♥'.repeat(Math.max(0,game.lives))||'0';ui.score.textContent=String(game.score).padStart(6,'0');ui.scrap.textContent=game.scrap;ui.level.textContent=String(Math.min(9,1+Math.floor(game.kills/8))).padStart(2,'0');ui.loadout.textContent='LOADOUT: '+(game.upgrades.length?game.upgrades.join(' · '):'EMPTY');if(game.boss){ui.bossbar.classList.add('show');ui.bossname.textContent=stages[game.stage].boss;ui.healthfill.style.width=Math.max(0,game.boss.hp/game.boss.max*100)+'%'}else ui.bossbar.classList.remove('show')}
function rand(a,b){return a+Math.random()*(b-a)}function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function burst(x,y,color,n=9){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=rand(45,180);game.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.25,.65),max:.65,color,r:rand(2,5)})}}
function enemySpawn(){let kind=Math.random();game.enemies.push({x:rand(44,W-44),y:-28,r:kind>.77?21:15,hp:kind>.77?4:2,max:kind>.77?4:2,speed:kind>.77?42:rand(65,90),type:kind>.77?'heavy':'regular',phase:rand(0,6),shot:rand(1,3),color:stages[game.stage].accent})}
function makeBoss(){if(game.boss)return;game.boss={x:W/2,y:100,r:53,hp:Math.round(140+game.stage*55),max:Math.round(140+game.stage*55),t:0,shot:.7,phase:0};game.enemies=[];game.ebullets=[];showToast('BOSS INBOUND',stages[game.stage].boss);updateHud()}
function firePlayer(){let p=game.player;if(!p)return;let count=p.spread,step=0.16;for(let i=0;i<count;i++){let a=(i-(count-1)/2)*step;game.bullets.push({x:p.x,y:p.y-20,vx:Math.sin(a)*30,vy:-490,damage:p.damage,r:5,color:cast[chosen].color})}p.shot=p.rate}
function useSpecial(){if(!game.active||game.paused||game.over||game.special>0)return;game.special=9;let p=game.player;burst(p.x,p.y,cast[chosen].color,34);game.shake=.3;let radius=chosen===2?260:215;game.ebullets=game.ebullets.filter(b=>{if(Math.hypot(b.x-p.x,b.y-p.y)<radius){burst(b.x,b.y,'#d4ff58',3);return false}return true});if(game.boss&&Math.hypot(game.boss.x-p.x,game.boss.y-p.y)<radius+65)game.boss.hp-=chosen===2?32:22;game.enemies.forEach(e=>{if(Math.hypot(e.x-p.x,e.y-p.y)<radius)e.hp-=8});showToast(cast[chosen].special,'TRASH BLAST READY')}
function update(dt){if(!game.active||game.paused)return;game.tick+=dt;game.time+=dt;let p=game.player;p.shot-=dt;p.inv=Math.max(0,p.inv-dt);p.hurt=Math.max(0,p.hurt-dt);game.special=Math.max(0,game.special-dt);game.shake=Math.max(0,game.shake-dt);
 let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(touchMove.x||touchMove.y){dx+=touchMove.x;dy+=touchMove.y}let mag=Math.hypot(dx,dy);if(mag){p.x+=dx/mag*p.speed*dt;p.y+=dy/mag*p.speed*dt}p.x=Math.max(24,Math.min(W-24,p.x));p.y=Math.max(55,Math.min(H-27,p.y));if(p.shot<=0)firePlayer();
 if(!game.boss){game.spawn-=dt;if(game.spawn<=0){enemySpawn();game.spawn=Math.max(.43,1.15-game.stage*.13)}if(game.time>31||game.kills>=14)makeBoss()}
 if(game.boss){let b=game.boss;b.t+=dt;b.x=W/2+Math.sin(b.t*.83)*245;b.y=91+Math.sin(b.t*1.35)*24;b.shot-=dt;if(b.shot<=0){let aim=Math.atan2(p.y-b.y,p.x-b.x),count=game.stage===0?5:7,speed=game.stage===2?185:155;for(let i=0;i<count;i++){let a=aim+(i-(count-1)/2)*.19;game.ebullets.push({x:b.x,y:b.y+25,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,r:7,color:game.stage===1?'#70edff':'#ff845f'})}if(game.stage>0)for(let i=0;i<8;i++){let a=b.t*1.7+i*Math.PI/4;game.ebullets.push({x:b.x,y:b.y,vx:Math.cos(a)*105,vy:Math.sin(a)*105,r:5,color:'#ffdb73'})}b.shot=game.stage===2?.8:1.12}if(b.hp<=0){burst(b.x,b.y,'#ffb561',48);game.score+=1800;game.scrap+=20;game.boss=null;updateHud();if(game.stage===2){finish(true);return}game.stage++;game.time=0;game.kills=0;game.spawn=2;game.ebullets=[];stageLabel();showToast('ZONE CLEAR',stages[game.stage].name)}}
 for(let i=game.enemies.length-1;i>=0;i--){let e=game.enemies[i];e.phase+=dt;e.y+=e.speed*dt;e.x+=Math.sin(e.phase*2)*22*dt;e.shot-=dt;if(e.shot<=0&&e.y>20&&e.y<H-100){let a=Math.atan2(p.y-e.y,p.x-e.x);game.ebullets.push({x:e.x,y:e.y,vx:Math.cos(a)*125,vy:Math.sin(a)*125,r:5,color:'#ff9c6e'});e.shot=rand(2.2,3.8)}if(e.y>H+30)game.enemies.splice(i,1)}
 game.bullets.forEach(b=>{b.x+=b.vx*dt;b.y+=b.vy*dt});game.bullets=game.bullets.filter(b=>b.y>-20&&b.x>-20&&b.x<W+20);
 game.ebullets.forEach(b=>{b.x+=b.vx*dt;b.y+=b.vy*dt});game.ebullets=game.ebullets.filter(b=>b.y<H+30&&b.x>-30&&b.x<W+30&&b.y>-30);
 for(let i=game.bullets.length-1;i>=0;i--){let a=game.bullets[i],hit=false;if(game.boss&&Math.hypot(a.x-game.boss.x,a.y-game.boss.y)<game.boss.r){game.boss.hp-=a.damage;hit=true}if(!hit){for(let j=game.enemies.length-1;j>=0;j--){let e=game.enemies[j];if(Math.hypot(a.x-e.x,a.y-e.y)<e.r+4){e.hp-=a.damage;hit=true;if(e.hp<=0){burst(e.x,e.y,e.color);game.score+=100;game.kills++;if(Math.random()<.23)drop(e.x,e.y);game.enemies.splice(j,1)}break}}}if(hit)game.bullets.splice(i,1)}
 for(let i=game.ebullets.length-1;i>=0;i--){let b=game.ebullets[i];if(p.inv<=0&&Math.hypot(b.x-p.x,b.y-p.y)<p.r+b.r){game.ebullets.splice(i,1);hurtPlayer();continue}if(game.enemies.some(e=>Math.hypot(b.x-e.x,b.y-e.y)<e.r+b.r)){} }
 for(let e of game.enemies){if(p.inv<=0&&Math.hypot(e.x-p.x,e.y-p.y)<e.r+p.r){e.hp=0;hurtPlayer()}}
 for(let i=game.pickups.length-1;i>=0;i--){let q=game.pickups[i];q.t+=dt;q.y+=Math.sin(q.t*3)*.2;if(Math.hypot(q.x-p.x,q.y-p.y)<p.r+18){collect(q);game.pickups.splice(i,1)}}
 game.particles.forEach(q=>{q.x+=q.vx*dt;q.y+=q.vy*dt;q.vx*=.97;q.vy*=.97;q.life-=dt});game.particles=game.particles.filter(q=>q.life>0);if(game.tick>.12){updateHud();game.tick=0}
}
function hurtPlayer(){game.lives--;game.player.inv=1.5;game.shake=.35;burst(game.player.x,game.player.y,'#ff7954',17);if(game.lives<=0)finish(false)}
function drop(x,y){let junk=junkTypes[Math.floor(Math.random()*junkTypes.length)];game.pickups.push({x,y,type:junk,t:0})}
function collect(q){let id=q.type.id,p=game.player;if(id==='pizza')p.spread=Math.min(5,p.spread+1);if(id==='rate')p.rate=Math.max(.07,p.rate*.84);if(id==='heart')game.lives=Math.min(5,game.lives+1);if(id==='damage')p.damage+=.35;if(id==='spread')p.spread=Math.min(5,p.spread+1);game.score+=250;game.scrap+=1;game.upgrades.push(q.type.icon);burst(q.x,q.y,'#d4ff58',12);showToast('JUNK POWER-UP!',q.type.icon+' '+q.type.desc);updateHud()}

